mapper.select:
select s.schedule_id, s.user_id, u.user_name, s.dept_id, d.dept_name, s.work_date,
s.shift_id, sh.shift_name, s.rest_type, s.schedule_remark
from hr_schedule s
left join sys_user u on u.user_id = s.user_id
left join sys_dept d on d.dept_id = s.dept_id
left join hr_shift sh on sh.shift_id = s.shift_id

    1=1
    and s.user_id = #{userId}
    and s.dept_id = #{deptId}
    and s.work_date = #{workDate}
    and s.work_date >= #{params.beginTime}
    and s.work_date <= #{params.endTime}

order by s.work_date desc, s.user_id asc

mapper.update:
update hr_schedule
user_id = #{userId}, dept_id = #{deptId}, work_date = #{workDate}, shift_id = #{shiftId}, rest_type = #{restType}, schedule_remark = #{scheduleRemark}, update_by = #{updateBy}, update_time = sysdate()
where schedule_id = #{scheduleId}
